function Timer()
{
    if (CountVersusPlayers() < 2)
    {
        if (VersusPhase != 'WaitingForPlayers')
            EnterWaitingForPlayers();
    }
    else if (VersusPhase == 'WaitingForPlayers')
        BeginVersusCountdown();
    else if ((VersusPhase == 'Countdown' || VersusPhase == 'MatchOver')
        && Level.TimeSeconds >= PhaseEndTime)
        BeginVersusMatch();

    if (VersusPhase != 'MatchOver')
        RespawnDeadPlayers();
    UpdateVersusGRI();
}

function int CountVersusPlayers()
{
    local Pawn P;
    local HPVersusHarry H;
    local int Count;

    for (P = Level.PawnList; P != None; P = P.NextPawn)
    {
        H = HPVersusHarry(P);
        if (H != None && H.Player != None)
            Count++;
    }
    return Count;
}

