function BeginVersusMatch()
{
    local Pawn P;
    local HPVersusHarry H;
    local HPVersusPRI PRI;
    local HPVersusSpell Spell;
    local HPVersusGRI G;

    if (CountVersusPlayers() < 2)
    {
        EnterWaitingForPlayers();
        return;
    }

    bMatchInProgress = False;
    foreach AllActors(Class'HPVersusSpell', Spell)
        Spell.Destroy();

    for (P = Level.PawnList; P != None; P = P.NextPawn)
    {
        H = HPVersusHarry(P);
        if (H == None || H.Player == None)
            continue;

        PRI = HPVersusPRI(H.PlayerReplicationInfo);
        if (PRI != None)
        {
            PRI.RoundScore = 0;
            PRI.Score = 0;
            PRI.Deaths = 0;
        }
        if (RestartPlayer(H))
        {
            H.SetupVersusPlayer();
            H.VersusRespawnAt = 0;
            H.ClientVersusRespawn();
        }
        else
        {
            H.bVersusDead = True;
            H.VersusRespawnAt = Level.TimeSeconds + 0.20;
            H.GotoState('VersusDead');
            H.ClientVersusDeath();
        }
    }

    G = HPVersusGRI(GameReplicationInfo);
    if (G != None)
        G.WinnerName = "";
    VersusPhase = 'InProgress';
    PhaseEndTime = 0;
    bMatchInProgress = True;
    BroadcastMessage("Versus match started!");
    Log("HPVersusMatch phase=InProgress players=" $ CountVersusPlayers());
}

